import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-DixIL8sc.js";var i=JSON.parse(`{"path":"/AI%E5%AE%9E%E8%B7%B5/AgentFramework/06_%E6%89%98%E7%AE%A1.html","title":"服务托管","lang":"zh-CN","frontmatter":{"title":"服务托管","icon":"fa6-solid:server","order":6,"category":["AI实践","Agent",".NET"]},"git":{"createdTime":1782290623000,"updatedTime":1782290623000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":10.99,"words":3298},"filePathRelative":"AI实践/AgentFramework/06_托管.md"}`),a={name:`06_托管.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="服务托管-hosting" tabindex="-1"><a class="header-anchor" href="#服务托管-hosting"><span>服务托管（Hosting）</span></a></h1><p>前 5 篇的所有代码都是本地跑的——控制台程序里 <code>await agent.RunAsync(...)</code> 拿结果。这一篇解决怎么把 Agent 和 Workflow 部署成服务，让用户和其他 Agent 能通过网络调用它。</p><hr><h2 id="_6-1-为什么需要托管" tabindex="-1"><a class="header-anchor" href="#_6-1-为什么需要托管"><span>6.1 为什么需要托管</span></a></h2><p>本地跑的 Agent 只能你自己用。真实业务里，Agent 至少要面对这几种调用方：</p><ul><li>前端 Web 应用，用户在网页里和 Agent 对话</li><li>移动 App</li><li>其他 Agent（多代理系统里互相调用）</li><li>业务系统通过 HTTP API 触发 Agent</li></ul><p>把这些场景统一抽象成&quot;把 Agent 暴露成网络服务&quot;，就是托管。框架给了几种托管方式，对应不同场景。</p><h2 id="_6-2-四种托管选项" tabindex="-1"><a class="header-anchor" href="#_6-2-四种托管选项"><span>6.2 四种托管选项</span></a></h2><p>官方列了四种，先了解各自适合什么：</p><p><strong>A2A 协议</strong>（Agent-to-Agent）——通过标准化的 A2A 协议暴露 Agent。适合多代理系统，尤其是跨框架、跨技术栈的代理互相通信。</p><p><strong>OpenAI-Compatible 端点</strong>——把 Agent 暴露成兼容 OpenAI Chat Completion 或 Responses API 的接口。适合已经有 OpenAI 兼容客户端、想无缝替换的场景。</p><p><strong>Durable Extension</strong>——让 Agent 和 Workflow 跑在 Azure Functions 或自托管计算上，支持持久化和长任务。适合需要长期稳定运行的工作负载。</p><p><strong>AG-UI 协议</strong>——专门给 Web 前端用的协议，方便构建基于浏览器的 AI Agent 应用。</p><p>这四种不是互斥的，同一个 Agent 可以同时通过多个协议暴露。下面重点讲 A2A 和 <a href="http://ASP.NET" target="_blank" rel="noopener noreferrer">ASP.NET</a> Core 托管，因为这是 .NET 开发者最常用的路径。</p><h2 id="_6-3-asp-net-core-托管的核心库" tabindex="-1"><a class="header-anchor" href="#_6-3-asp-net-core-托管的核心库"><span>6.3 <a href="http://ASP.NET" target="_blank" rel="noopener noreferrer">ASP.NET</a> Core 托管的核心库</span></a></h2><p><code>Microsoft.Agents.AI.Hosting</code> 是基础托管库，提供把 AI Agent 集成到 <a href="http://ASP.NET" target="_blank" rel="noopener noreferrer">ASP.NET</a> Core 应用的扩展方法。它的核心思路是把 Agent 注册到依赖注入容器里，让 Agent 能用应用的基础设施（配置、日志、数据库连接等），同时让外部协议适配器能从容器里取出 Agent 来调用。</p><p>整个过程可以这样理解：托管库是个&quot;协议适配器&quot;——外部请求通过协议特定的中间件进来，被翻译成对 <code>AIAgent</code> 的调用，响应再被翻译回协议格式。Agent 实现本身和协议无关，换协议不用改 Agent 代码。</p><h3 id="_6-3-1-注册-ichatclient" tabindex="-1"><a class="header-anchor" href="#_6-3-1-注册-ichatclient"><span>6.3.1 注册 IChatClient</span></a></h3><p>在配置 Agent 之前，先把 <code>IChatClient</code> 注册到 DI 容器。<code>IChatClient</code> 是和底层 LLM 服务通信的客户端，Agent 通过它调模型。</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#7F848E;font-style:italic;">// endpoint 是你的 Microsoft Foundry 项目端点</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// deploymentName 比如 &quot;gpt-4o-mini&quot;</span></span>
<span class="line"><span style="color:#E5C07B;">IChatClient</span><span style="color:#E06C75;"> chatClient</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">AIProjectClient</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#ABB2BF;">        new </span><span style="color:#E5C07B;">Uri</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">endpoint</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        new </span><span style="color:#E5C07B;">DefaultAzureCredential</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">GetProjectOpenAIClient</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">GetProjectResponsesClient</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">AsIChatClient</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">deploymentName</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">builder</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Services</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddSingleton</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">chatClient</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>DefaultAzureCredential</code> 还是那句话——开发方便，生产环境换 <code>ManagedIdentityCredential</code>。</p><h3 id="_6-3-2-用-addaiagent-注册-agent" tabindex="-1"><a class="header-anchor" href="#_6-3-2-用-addaiagent-注册-agent"><span>6.3.2 用 AddAIAgent 注册 Agent</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> pirateAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#98C379;">    &quot;pirate&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E5C07B;">    instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a pirate. Speak like a pirate&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E5C07B;">    description</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;An agent that speaks like a pirate.&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E5C07B;">    chatClientServiceKey</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;chat-model&quot;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>AddAIAgent</code> 返回一个 <code>IHostedAgentBuilder</code>，可以链式配置 Agent。比如加工具：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> pirateAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;pirate&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a pirate. Speak like a pirate&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">WithAITool</span><span style="color:#ABB2BF;">(new </span><span style="color:#E5C07B;">MyTool</span><span style="color:#ABB2BF;">()); </span><span style="color:#7F848E;font-style:italic;">// MyTool 是自定义 AITool 派生类</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>或者配会话存储：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> pirateAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;pirate&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a pirate. Speak like a pirate&quot;</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">WithInMemorySessionStore</span><span style="color:#ABB2BF;">();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>WithInMemorySessionStore</code> 是开发用的，生产环境要换成持久化存储——这块和第 4 篇讲的 ChatHistoryProvider 是一回事，只是这里通过托管库的扩展方法配置。</p><h3 id="_6-3-3-用-addworkflow-注册工作流" tabindex="-1"><a class="header-anchor" href="#_6-3-3-用-addworkflow-注册工作流"><span>6.3.3 用 AddWorkflow 注册工作流</span></a></h3><p>工作流也能托管。下面这个例子把两个 Agent 串成顺序工作流——用户输入先进 agent-1，响应再进 agent-2，最终输出：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#E5C07B;">builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;agent-1&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;you are agent 1!&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E5C07B;">builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;agent-2&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;you are agent 2!&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> workflow</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddWorkflow</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;my-workflow&quot;</span><span style="color:#ABB2BF;">, (</span><span style="color:#E5C07B;">sp</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">key</span><span style="color:#ABB2BF;">) =&gt;</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> agent1</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> sp</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetRequiredKeyedService</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">AIAgent</span><span style="color:#ABB2BF;">&gt;(</span><span style="color:#98C379;">&quot;agent-1&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> agent2</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> sp</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetRequiredKeyedService</span><span style="color:#ABB2BF;">&lt;</span><span style="color:#E5C07B;">AIAgent</span><span style="color:#ABB2BF;">&gt;(</span><span style="color:#98C379;">&quot;agent-2&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#E5C07B;"> AgentWorkflowBuilder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">BuildSequential</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">key</span><span style="color:#ABB2BF;">, [</span><span style="color:#E06C75;">agent1</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">agent2</span><span style="color:#ABB2BF;">]);</span></span>
<span class="line"><span style="color:#ABB2BF;">});</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意这里 lambda 的两个参数：<code>sp</code> 是 <code>IServiceProvider</code>，用来从 DI 容器取依赖；<code>key</code> 是工作流的名字，会传给 <code>AgentWorkflowBuilder</code>。<code>AgentWorkflowBuilder.BuildSequential</code> 是个便捷方法，把多个 Agent 按顺序串起来。还有个 <code>BuildConcurrent</code> 创建并发执行的工作流。</p><h3 id="_6-3-4-把工作流转成-agent-暴露" tabindex="-1"><a class="header-anchor" href="#_6-3-4-把工作流转成-agent-暴露"><span>6.3.4 把工作流转成 Agent 暴露</span></a></h3><p>工作流本身不能直接通过 A2A 或 OpenAI 协议暴露——这些协议期望的是 <code>AIAgent</code> 接口。所以要先转换：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> workflowAsAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E06C75;"> builder</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">AddWorkflow</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;science-workflow&quot;</span><span style="color:#ABB2BF;">, (</span><span style="color:#E5C07B;">sp</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">key</span><span style="color:#ABB2BF;">) =&gt; { ... })</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">AddAsAIAgent</span><span style="color:#ABB2BF;">();  </span><span style="color:#7F848E;font-style:italic;">// 现在工作流可以当 Agent 用了</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>AddAsAIAgent()</code> 把工作流包装成 <code>AIAgent</code>，之后所有对 Agent 适用的协议集成都能用上。这是工作流接入协议层的标准姿势。</p><h2 id="_6-4-通过-a2a-协议暴露-agent" tabindex="-1"><a class="header-anchor" href="#_6-4-通过-a2a-协议暴露-agent"><span>6.4 通过 A2A 协议暴露 Agent</span></a></h2><p>A2A 是个标准化协议，支持四件事：通过 AgentCard 发现代理、基于消息的代理间通信、通过任务支持长时间运行的代理进程、跨框架互操作。说白了就是让不同技术栈写的代理能互相说话。</p><p>A2A 协议规范在 <a href="https://a2a-protocol.org/latest/%EF%BC%8C%E6%83%B3%E6%B7%B1%E5%85%A5%E5%8F%AF%E4%BB%A5%E7%9C%8B%E3%80%82%E6%97%A5%E5%B8%B8%E7%94%A8%E4%B8%8D%E9%9C%80%E8%A6%81%E8%AF%BB%E8%A7%84%E8%8C%83%EF%BC%8C%E6%A1%86%E6%9E%B6%E5%B0%81%E8%A3%85%E5%A5%BD%E4%BA%86%E3%80%82" target="_blank" rel="noopener noreferrer">https://a2a-protocol.org/latest/，想深入可以看。日常用不需要读规范，框架封装好了。</a></p><h3 id="_6-4-1-装-nuget-包" tabindex="-1"><a class="header-anchor" href="#_6-4-1-装-nuget-包"><span>6.4.1 装 NuGet 包</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="color:#7F848E;font-style:italic;"># A2A 协议的 ASP.NET Core 集成</span></span>
<span class="line"><span style="color:#61AFEF;">dotnet</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> package</span><span style="color:#98C379;"> Microsoft.Agents.AI.Hosting.A2A.AspNetCore</span><span style="color:#D19A66;"> --prerelease</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;"># 连接 Microsoft Foundry 需要的</span></span>
<span class="line"><span style="color:#61AFEF;">dotnet</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> package</span><span style="color:#98C379;"> Azure.AI.Projects</span><span style="color:#D19A66;"> --prerelease</span></span>
<span class="line"><span style="color:#61AFEF;">dotnet</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> package</span><span style="color:#98C379;"> Azure.Identity</span></span>
<span class="line"><span style="color:#61AFEF;">dotnet</span><span style="color:#98C379;"> add</span><span style="color:#98C379;"> package</span><span style="color:#98C379;"> Microsoft.Agents.AI.Foundry</span><span style="color:#D19A66;"> --prerelease</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_6-4-2-完整的最小-a2a-服务端" tabindex="-1"><a class="header-anchor" href="#_6-4-2-完整的最小-a2a-服务端"><span>6.4.2 完整的最小 A2A 服务端</span></a></h3><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> A2A</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">AspNetCore</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> Azure</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">AI</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Projects</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> Azure</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Identity</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> Microsoft</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Agents</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">AI</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> Microsoft</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Agents</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">AI</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Hosting</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"><span style="color:#C678DD;">using</span><span style="color:#E5C07B;"> Microsoft</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Extensions</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">AI</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> builder</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> WebApplication</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">CreateBuilder</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">args</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">string</span><span style="color:#E06C75;"> endpoint</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Configuration</span><span style="color:#ABB2BF;">[</span><span style="color:#98C379;">&quot;AZURE_OPENAI_ENDPOINT&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    ?? </span><span style="color:#C678DD;">throw</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">InvalidOperationException</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;AZURE_OPENAI_ENDPOINT is not set.&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">string</span><span style="color:#E06C75;"> deploymentName</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Configuration</span><span style="color:#ABB2BF;">[</span><span style="color:#98C379;">&quot;AZURE_OPENAI_DEPLOYMENT_NAME&quot;</span><span style="color:#ABB2BF;">]</span></span>
<span class="line"><span style="color:#ABB2BF;">    ?? </span><span style="color:#C678DD;">throw</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">InvalidOperationException</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;AZURE_OPENAI_DEPLOYMENT_NAME is not set.&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// 注册 IChatClient</span></span>
<span class="line"><span style="color:#E5C07B;">IChatClient</span><span style="color:#E06C75;"> chatClient</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">AIProjectClient</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#ABB2BF;">        new </span><span style="color:#E5C07B;">Uri</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">endpoint</span><span style="color:#ABB2BF;">),</span></span>
<span class="line"><span style="color:#ABB2BF;">        new </span><span style="color:#E5C07B;">DefaultAzureCredential</span><span style="color:#ABB2BF;">())</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">GetProjectOpenAIClient</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">GetProjectResponsesClient</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">    .</span><span style="color:#61AFEF;">AsIChatClient</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">deploymentName</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E5C07B;">builder</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Services</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddSingleton</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">chatClient</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// 注册 Agent</span></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> pirateAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;pirate&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a pirate. Speak like a pirate.&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> app</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Build</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// 通过 A2A 协议暴露 Agent</span></span>
<span class="line"><span style="color:#E5C07B;">app</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">MapA2A</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">pirateAgent</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">path</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;/a2a/pirate&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">agentCard</span><span style="color:#ABB2BF;">: new()</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">    Name</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &quot;Pirate Agent&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    Description</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &quot;An agent that speaks like a pirate.&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    Version</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &quot;1.0&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">app</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Run</span><span style="color:#ABB2BF;">();</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>跑起来之后，<code>/a2a/pirate</code> 就是这个 Agent 的 A2A 端点。<code>MapA2A</code> 把 Agent 挂到指定路径，附带的 <code>agentCard</code> 是这个 Agent 的&quot;名片&quot;。</p><h3 id="_6-3-3-测试这个端点" tabindex="-1"><a class="header-anchor" href="#_6-3-3-测试这个端点"><span>6.3.3 测试这个端点</span></a></h3><p>启动服务后，发个 HTTP 请求就能调：</p><div class="language-http line-numbers-mode" data-highlighter="shiki" data-ext="http" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-http"><span class="line"><span style="color:#C678DD;">POST</span><span style="color:#ABB2BF;"> {{baseAddress}}/a2a/pirate/v1/message:stream</span></span>
<span class="line"><span style="color:#E06C75;">Content-Type</span><span style="color:#C678DD;">:</span><span style="color:#98C379;"> application/json</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;message&quot;</span><span style="color:#ABB2BF;">: {</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;kind&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;message&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;role&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;user&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;parts&quot;</span><span style="color:#ABB2BF;">: [</span></span>
<span class="line"><span style="color:#ABB2BF;">      {</span></span>
<span class="line"><span style="color:#E06C75;">        &quot;kind&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;text&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        &quot;text&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;Hey pirate! Tell me where have you been&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">        &quot;metadata&quot;</span><span style="color:#ABB2BF;">: {}</span></span>
<span class="line"><span style="color:#ABB2BF;">      }</span></span>
<span class="line"><span style="color:#ABB2BF;">    ],</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;messageId&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">null</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">    &quot;contextId&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;foo&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">  }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>响应长这样：</p><div class="language-json line-numbers-mode" data-highlighter="shiki" data-ext="json" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-json"><span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;kind&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;message&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;role&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;agent&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;parts&quot;</span><span style="color:#ABB2BF;">: [</span></span>
<span class="line"><span style="color:#ABB2BF;">    {</span></span>
<span class="line"><span style="color:#E06C75;">      &quot;kind&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;text&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">      &quot;text&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;Arrr, ye scallywag! ...&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">  ],</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;messageId&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;chatcmpl-CXtJbis...&quot;</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E06C75;">  &quot;contextId&quot;</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;foo&quot;</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>请求里的两个字段值得注意：</p><ul><li><code>messageId</code>——这条消息的唯一标识，自己生成 GUID 也行，传 <code>null</code> 让 Agent 自动生成</li><li><code>contextId</code>——<strong>会话标识</strong>。自己传一个 ID 就是开新对话，复用之前的 <code>contextId</code> 就是续上之前的对话。Agent 会保留同一个 <code>contextId</code> 的会话历史。不传就自动生成。</li></ul><p>这个 <code>contextId</code> 和第 3、4 章讲的 Session 是一回事——A2A 协议层叫 <code>contextId</code>，框架内部叫 <code>service_session_id</code>，两者自动映射。</p><h3 id="_6-4-4-agentcard-是什么" tabindex="-1"><a class="header-anchor" href="#_6-4-4-agentcard-是什么"><span>6.4.4 AgentCard 是什么</span></a></h3><p><code>AgentCard</code> 是 A2A 协议的&quot;代理名片&quot;，用来让其他 Agent 发现你、了解你的能力。属性有：</p><ul><li><code>Name</code>——显示名</li><li><code>Description</code>——简短说明</li><li><code>Version</code>——版本号</li><li><code>URL</code>——端点 URL，不指定会自动分配</li><li><code>Capabilities</code>——可选元数据，说明是否支持流式、推送通知等</li></ul><p>通过 <code>GET /a2a/pirate/v1/card</code> 能拿到这张名片。其他 Agent 调你之前，先 GET 这张卡了解你是什么 Agent、支持什么能力。</p><h3 id="_6-4-5-一个服务暴露多个-agent" tabindex="-1"><a class="header-anchor" href="#_6-4-5-一个服务暴露多个-agent"><span>6.4.5 一个服务暴露多个 Agent</span></a></h3><p>只要端点路径不冲突，一个 <a href="http://ASP.NET" target="_blank" rel="noopener noreferrer">ASP.NET</a> Core 应用可以挂多个 Agent：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> mathAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;math&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a math expert.&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> scienceAgent</span><span style="color:#56B6C2;"> =</span><span style="color:#E5C07B;"> builder</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">AddAIAgent</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;science&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">instructions</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;You are a science expert.&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E5C07B;">app</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">MapA2A</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">mathAgent</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;/a2a/math&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E5C07B;">app</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">MapA2A</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">scienceAgent</span><span style="color:#ABB2BF;">, </span><span style="color:#98C379;">&quot;/a2a/science&quot;</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种结构适合把一组相关的 Agent 部署在一起，共用底层 IChatClient 和基础设施。</p><h2 id="_6-5-作为客户端调用远程-a2a-agent" tabindex="-1"><a class="header-anchor" href="#_6-5-作为客户端调用远程-a2a-agent"><span>6.5 作为客户端调用远程 A2A Agent</span></a></h2><p>托管不光是&quot;暴露 Agent&quot;，反过来——调用远程 A2A Agent 也是托管的一部分。<code>A2AAgent</code> 类把任何远程 A2A 端点包装成本地 Agent，调用方式和你自己创建的 Agent 一模一样。</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#7F848E;font-style:italic;">// 用 A2AAgent 包装远程 A2A 端点</span></span>
<span class="line"><span style="color:#C678DD;">async</span><span style="color:#E5C07B;"> Task</span><span style="color:#61AFEF;"> Main</span><span style="color:#ABB2BF;">()</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#C678DD;">    string</span><span style="color:#E06C75;"> a2aHost</span><span style="color:#56B6C2;"> =</span><span style="color:#98C379;"> &quot;https://your-a2a-agent.example.com&quot;</span><span style="color:#ABB2BF;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 1. 先发现远程 Agent 的能力（拿 AgentCard）</span></span>
<span class="line"><span style="color:#C678DD;">    using</span><span style="color:#C678DD;"> var</span><span style="color:#E06C75;"> httpClient</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">HttpClient</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> cardResolver</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">A2ACardResolver</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">httpClient</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">a2aHost</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E5C07B;">    AgentCard</span><span style="color:#E06C75;"> card</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">cardResolver</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">GetAgentCardAsync</span><span style="color:#ABB2BF;">();</span></span>
<span class="line"><span style="color:#E5C07B;">    Console</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">WriteLine</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">$&quot;Found agent: </span><span style="color:#ABB2BF;">{</span><span style="color:#E5C07B;">card</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Name</span><span style="color:#ABB2BF;">}</span><span style="color:#98C379;">&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 2. 创建 A2AAgent 并发消息</span></span>
<span class="line"><span style="color:#C678DD;">    using</span><span style="color:#C678DD;"> var</span><span style="color:#E06C75;"> agent</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">A2AAgent</span><span style="color:#ABB2BF;">(</span></span>
<span class="line"><span style="color:#E5C07B;">        name</span><span style="color:#ABB2BF;">: </span><span style="color:#E5C07B;">card</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Name</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E5C07B;">        agentCard</span><span style="color:#ABB2BF;">: </span><span style="color:#E06C75;">card</span><span style="color:#ABB2BF;">,</span></span>
<span class="line"><span style="color:#E5C07B;">        url</span><span style="color:#ABB2BF;">: </span><span style="color:#E06C75;">a2aHost</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> response</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">agent</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">RunAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;What are your capabilities?&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#C678DD;">    foreach</span><span style="color:#ABB2BF;"> (</span><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> message</span><span style="color:#C678DD;"> in</span><span style="color:#E5C07B;"> response</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Messages</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">    {</span></span>
<span class="line"><span style="color:#E5C07B;">        Console</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">WriteLine</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">message</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Text</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">    }</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>A2AAgent</code> 帮你处理了所有协议细节——拿 AgentCard、序列化请求、解析响应、管理会话。你写的代码和调本地 Agent 没区别。</p><h3 id="_6-5-1-长任务的-background-模式" tabindex="-1"><a class="header-anchor" href="#_6-5-1-长任务的-background-模式"><span>6.5.1 长任务的 background 模式</span></a></h3><p>默认 <code>RunAsync</code> 会等远程 Agent 跑完才返回。长任务可能跑几分钟几小时，不能傻等。这时用 <code>background</code> 模式：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#7F848E;font-style:italic;">// 启动长任务，立即返回 continuation token</span></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> response</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">agent</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">RunAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Process this large dataset&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E5C07B;">background</span><span style="color:#ABB2BF;">: </span><span style="color:#D19A66;">true</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#C678DD;">if</span><span style="color:#ABB2BF;"> (</span><span style="color:#E5C07B;">response</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">ContinuationToken</span><span style="color:#ABB2BF;"> is not </span><span style="color:#D19A66;">null</span><span style="color:#ABB2BF;">)</span></span>
<span class="line"><span style="color:#ABB2BF;">{</span></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">    // 之后用 token 轮询结果</span></span>
<span class="line"><span style="color:#C678DD;">    var</span><span style="color:#E06C75;"> result</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">agent</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">PollTaskAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">response</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">ContinuationToken</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#E5C07B;">    Console</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">WriteLine</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;">result</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"><span style="color:#ABB2BF;">}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>这种&quot;启动—拿 token—之后轮询&quot;的模式是处理长任务的标准做法。配合 Durable Extension 能做更优雅的回调通知，不用傻轮询。</p><h3 id="_6-5-2-会话连续性" tabindex="-1"><a class="header-anchor" href="#_6-5-2-会话连续性"><span>6.5.2 会话连续性</span></a></h3><p><code>A2AAgent</code> 调用时如果传了 <code>AgentSession</code>，会自动从 <code>session.ServiceSessionId</code> 派生出 A2A 的 <code>context_id</code>。这样跨多次 A2A 调用保持会话连续，不用每次手动设 <code>context_id</code>：</p><div class="language-csharp line-numbers-mode" data-highlighter="shiki" data-ext="csharp" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-csharp"><span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> session</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> new </span><span style="color:#E5C07B;">AgentSession</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">serviceSessionId</span><span style="color:#ABB2BF;">: </span><span style="color:#98C379;">&quot;my-conversation-1&quot;</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// context_id 自动设成 &quot;my-conversation-1&quot;</span></span>
<span class="line"><span style="color:#C678DD;">var</span><span style="color:#E06C75;"> response</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">agent</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">RunAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Hello!&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">session</span><span style="color:#ABB2BF;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#7F848E;font-style:italic;">// 同一个 session 继续聊</span></span>
<span class="line"><span style="color:#E06C75;">response</span><span style="color:#56B6C2;"> =</span><span style="color:#ABB2BF;"> await </span><span style="color:#E5C07B;">agent</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">RunAsync</span><span style="color:#ABB2BF;">(</span><span style="color:#98C379;">&quot;Follow-up question&quot;</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">session</span><span style="color:#ABB2BF;">);</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>如果消息里显式带了 <code>context_id</code>，那个值优先。这个优先级要记住——显式 &gt; 自动派生。</p><h2 id="_6-6-持久化托管-durable-extension" tabindex="-1"><a class="header-anchor" href="#_6-6-持久化托管-durable-extension"><span>6.6 持久化托管：Durable Extension</span></a></h2><p><a href="http://ASP.NET" target="_blank" rel="noopener noreferrer">ASP.NET</a> Core 托管适合短交互——请求来、Agent 响应、连接关。但有些场景需要 Agent 长时间运行、跨多次调用保持状态、出故障能恢复，这时用 Durable Extension。</p><p>Durable Extension 让 Agent 和 Workflow 跑在 Azure Functions 或自托管计算上，提供：</p><ul><li>持久化状态——进程重启不丢</li><li>长任务支持——可以跑几小时几天</li><li>故障恢复——失败的任务能从检查点续上</li><li>自动伸缩——按负载扩缩容</li></ul><p>Durable Extension 和第 5 篇讲的超级步骤检查点是配套的——工作流在超级步骤边界保存检查点，崩了能从最近的检查点恢复，不用从头跑。</p><p>具体配置涉及 Azure Functions 的细节比较多，入门阶段知道有这个选项就行，需要时查官方的 Durable Agents 示例。</p><h2 id="_6-7-协议、agent、workflow-三者的关系" tabindex="-1"><a class="header-anchor" href="#_6-7-协议、agent、workflow-三者的关系"><span>6.7 协议、Agent、Workflow 三者的关系</span></a></h2><p>到这里你可能有疑问：协议（A2A/OpenAI）、Agent、Workflow 到底怎么组合？理清楚：</p><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="background-color:#282c34;color:#abb2bf;"><pre class="shiki one-dark-pro vp-code"><code class="language-"><span class="line"><span>                        ┌─────────────────┐</span></span>
<span class="line"><span>外部请求 ──→ 协议适配器 ──→│  AIAgent 实例   │</span></span>
<span class="line"><span>（A2A/HTTP）              │  (或 Workflow   │</span></span>
<span class="line"><span>                        │   包装成 Agent) │</span></span>
<span class="line"><span>                        └─────────────────┘</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span>                                ↓</span></span>
<span class="line"><span>                          IChatClient</span></span>
<span class="line"><span>                                │</span></span>
<span class="line"><span>                                ↓</span></span>
<span class="line"><span>                            LLM 服务</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：</p><ol><li><strong>协议层只认 <code>AIAgent</code></strong>——不管你后面是单 Agent 还是 Workflow，对外都得是 <code>AIAgent</code>。Workflow 要用 <code>AddAsAIAgent()</code> 转换。</li><li><strong>Agent 实例从 DI 容器拿</strong>——<code>AddAIAgent</code> 注册的 Agent 在容器里，协议适配器从容器取出来用。</li><li><strong>同一个 Agent 能挂多个协议</strong>——同时通过 A2A 和 OpenAI-Compatible 端点暴露，Agent 代码不动。</li><li><strong><code>IChatClient</code> 是底层依赖</strong>——所有 Agent 共用一个，通过 DI 注入。</li></ol><p>理解了这个分层，后面碰到的所有托管场景都能套进去。</p><h2 id="_6-8-几个注意事项" tabindex="-1"><a class="header-anchor" href="#_6-8-几个注意事项"><span>6.8 几个注意事项</span></a></h2><p><strong>生产环境必须换 <code>DefaultAzureCredential</code></strong>。前面几章反复说过，这里再说一次。生产环境用 <code>ManagedIdentityCredential</code> 或其他特定凭证，否则有安全风险和性能问题——<code>DefaultAzureCredential</code> 会按顺序尝试多种凭证，每个失败的尝试都增加延迟。</p><p><strong><code>WithInMemorySessionStore</code> 只能开发用</strong>。生产环境必须换成持久化存储，否则服务重启所有会话历史丢失，用户回来发现 Agent &quot;失忆&quot;了。第 4 篇讲的自定义 <code>ChatHistoryProvider</code> 在这里通过 <code>WithSessionStorage</code>（或类似扩展方法）接入。</p><p><strong>长任务别让 HTTP 请求一直挂着</strong>。HTTP 请求默认超时几十秒到几分钟，长任务必须用 <code>background</code> 模式启动 + 轮询/回调拿结果。直接 <code>await agent.RunAsync(...)</code> 等几小时，网关和浏览器都会先断开。</p><p><strong>一个端点路径只能挂一个 Agent</strong>。<code>MapA2A</code> 的 <code>path</code> 参数必须唯一，否则启动报错。多 Agent 用不同路径区分。</p><p><strong>AgentCard 要写清楚</strong>。其他 Agent 是靠 AgentCard 决定要不要调你的——Description 含糊，可能被误调或漏调。这和工具的 <code>[Description]</code> 一个道理。</p><p><strong>Workflow 不能直接暴露</strong>。必须 <code>AddAsAIAgent()</code> 转换成 Agent。忘了这步会发现在 <code>MapA2A</code> 那里编译不过，因为参数类型不对。</p><p><strong>C# 侧 <code>A2AAgent</code> 客户端要 dispose</strong>。它持有 HTTP 连接，用完不释放会泄漏连接。用 <code>using</code> 或 <code>await using</code> 包起来。</p><h2 id="_6-9-自测题" tabindex="-1"><a class="header-anchor" href="#_6-9-自测题"><span>6.9 自测题</span></a></h2><ol><li>托管库为什么要把 Agent 注册到 DI 容器，而不是直接 <code>new</code> 出来？</li><li><code>AddAIAgent</code> 和 <code>AddWorkflow</code> 注册的东西，分别是什么类型？</li><li>一个 Workflow 要通过 A2A 暴露，需要做什么转换？为什么必须做？</li><li>A2A 请求里的 <code>contextId</code> 是干什么的？不传会怎样？</li><li><code>A2AAgent</code> 是什么？它和你自己 <code>AddAIAgent</code> 注册的 Agent 有什么区别？</li><li>长任务为什么不能直接 <code>await agent.RunAsync(...)</code>？应该怎么处理？</li><li>协议、Agent、IChatClient 三者的依赖关系是什么？谁依赖谁？</li><li>生产环境 <code>DefaultAzureCredential</code> 为什么不能用？换什么？</li></ol><hr><p>到这里，官方&quot;入门 6 步&quot;全部讲完。认知地图应该是这样：</p><ul><li><strong>第 1 篇</strong>：Agent 是什么、怎么创建和调用</li><li><strong>第 2 篇</strong>：给 Agent 加工具，function calling 机制</li><li><strong>第 3 篇</strong>：Session 让 Agent 跨轮次记忆</li><li><strong>第 4 篇</strong>：持久化让记忆活下来</li><li><strong>第 5 篇</strong>：Workflow 编排多步骤业务流程</li><li><strong>第 6 篇</strong>：把 Agent/Workflow 部署成服务</li></ul><p>接下来进入<strong>深入核心</strong>——Agent 类型体系、中间件、技能、上下文提供程序，以及工作流的状态、检查点、事件机制。这些前面 6 篇都涉及过，后面会展开讲边界、对比、选型。</p>`,98)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};